// `{{regexp.match(email.local(external.trait_name))}}`
package parse

import (
	"go/ast"
	"go/parser"
	"go/token"
	"net/mail"
	"regexp"
	"strconv"
	"strings"
	"unicode"

	"github.com/gravitational/trace"

