func buildIdentifier(parts []string) (interface{}, error) {
	if len(parts) == 1 {
		if parts[0] == "internal" || parts[0] == "external" || parts[0] == LiteralNamespace {
			return namespaceRef{parts[0]}, nil
		}
		return nil, trace.BadParameter("incomplete variable %q; expected namespace.name", parts[0])
	}
	return buildVarExpr(parts)
}
func asExpr(v interface{}) (Expr, error) {
	e, ok := v.(Expr)
	if !ok {
		return nil, trace.BadParameter("expected string expression, got %T", v)
	}
	if e.Kind() != reflect.Slice {
		return nil, trace.BadParameter("expected string expression, got %s", fmt.Sprint(e.Kind()))
	}
	return e, nil
}

package parse

import (
	"fmt"
	"net/mail"
	"reflect"
	"regexp"
	"strconv"
	"strings"

	"github.com/gravitational/trace"
)

// Expr is a typed expression node.
type Expr interface {
	Evaluate(EvaluateContext) (any, error)
	Kind() reflect.Kind
	String() string
}

// EvaluateContext provides the inputs needed to evaluate an expression.
type EvaluateContext struct {
	VarValue     func(VarExpr) ([]string, error)
	MatcherInput string
}

type StringLitExpr struct{ Value string }

func (e StringLitExpr) String() string                        { return strconv.Quote(e.Value) }
func (StringLitExpr) Kind() reflect.Kind                      { return reflect.String }
func (e StringLitExpr) Evaluate(EvaluateContext) (any, error) { return []string{e.Value}, nil }

type VarExpr struct{ Namespace, Name string }

func (e VarExpr) String() string   { return e.Namespace + "." + e.Name }
func (VarExpr) Kind() reflect.Kind { return reflect.String }
func (e VarExpr) Evaluate(ctx EvaluateContext) (any, error) {
	if ctx.VarValue == nil {
		return nil, trace.BadParameter("no variable resolver for %s", e)
	}
	return ctx.VarValue(e)
}

type EmailLocalExpr struct{ Inner Expr }

func (e EmailLocalExpr) String() string   { return "email.local(" + e.Inner.String() + ")" }
func (EmailLocalExpr) Kind() reflect.Kind { return reflect.String }
func (e EmailLocalExpr) Evaluate(ctx EvaluateContext) (any, error) {
	values, err := evalStrings(e.Inner, ctx)
	if err != nil {
		return nil, err
	}
	out := make([]string, 0, len(values))
	for _, value := range values {
		if value == "" {
			return nil, trace.BadParameter("email.local input is empty")
		}
		addr, err := mail.ParseAddress(value)
		if err != nil {
			return nil, trace.BadParameter("email.local could not parse address %q: %v", value, err)
		}
		at := strings.LastIndexByte(addr.Address, '@')
		if at <= 0 {
			return nil, trace.BadParameter("email.local address %q has no local part", addr.Address)
		}
		out = append(out, addr.Address[:at])
	}
	return out, nil
}

type RegexpReplaceExpr struct {
	Inner                Expr
	Pattern, Replacement string
	re                   *regexp.Regexp
}

func (e RegexpReplaceExpr) String() string {
	return "regexp.replace(" + e.Inner.String() + ", " + strconv.Quote(e.Pattern) + ", " + strconv.Quote(e.Replacement) + ")"
}
func (RegexpReplaceExpr) Kind() reflect.Kind { return reflect.String }
func (e RegexpReplaceExpr) Evaluate(ctx EvaluateContext) (any, error) {
	values, err := evalStrings(e.Inner, ctx)
	if err != nil {
		return nil, err
	}
	re := e.re
	if re == nil {
		re, err = compileRegex(e.Pattern)
		if err != nil {
			return nil, err
		}
	}
	out := make([]string, 0, len(values))
	for _, value := range values {
		if re.MatchString(value) {
			out = append(out, re.ReplaceAllString(value, e.Replacement))
		}
	}
	return out, nil
}

type RegexpMatchExpr struct {
	Pattern string
	re      *regexp.Regexp
}

func (e RegexpMatchExpr) String() string   { return "regexp.match(" + strconv.Quote(e.Pattern) + ")" }
func (RegexpMatchExpr) Kind() reflect.Kind { return reflect.Bool }
func (e RegexpMatchExpr) Evaluate(ctx EvaluateContext) (any, error) {
	re, err := e.compiled()
	if err != nil {
		return nil, err
	}
	return re.MatchString(ctx.MatcherInput), nil
}
func (e RegexpMatchExpr) compiled() (*regexp.Regexp, error) {
	if e.re != nil {
		return e.re, nil
	}
	return compileRegex(e.Pattern)
}

type RegexpNotMatchExpr struct {
	Pattern string
	re      *regexp.Regexp
}

func (e RegexpNotMatchExpr) String() string {
	return "regexp.not_match(" + strconv.Quote(e.Pattern) + ")"
}
func (RegexpNotMatchExpr) Kind() reflect.Kind { return reflect.Bool }
func (e RegexpNotMatchExpr) Evaluate(ctx EvaluateContext) (any, error) {
	re, err := e.compiled()
	if err != nil {
		return nil, err
	}
	return !re.MatchString(ctx.MatcherInput), nil
}
func (e RegexpNotMatchExpr) compiled() (*regexp.Regexp, error) {
	if e.re != nil {
		return e.re, nil
	}
	return compileRegex(e.Pattern)
}

func compileRegex(pattern string) (*regexp.Regexp, error) {
	re, err := regexp.Compile(pattern)
	if err != nil {
		return nil, trace.BadParameter("invalid regexp pattern %q: %v", pattern, err)
	}
	return re, nil
}
func evalStrings(expr Expr, ctx EvaluateContext) ([]string, error) {
	if expr == nil || expr.Kind() != reflect.String {
		return nil, trace.BadParameter("expected string expression, got %v", expr)
	}
	v, err := expr.Evaluate(ctx)
	if err != nil {
		return nil, err
	}
	values, ok := v.([]string)
	if !ok {
		return nil, trace.BadParameter("expected string expression result, got %T", v)
	}
	return values, nil
}
func validateExpr(expr Expr) error {
	var visit func(Expr) error
	visit = func(node Expr) error {
		switch n := node.(type) {
		case VarExpr:
			if n.Name == "" {
				return trace.BadParameter("variable must have the form namespace.name")
			}
		case EmailLocalExpr:
			return visit(n.Inner)
		case RegexpReplaceExpr:
			return visit(n.Inner)
		}
		return nil
	}
	return visit(expr)
}

type namespaceRef struct{ namespace string }

func buildVarExpr(parts []string) (interface{}, error) {
	if len(parts) != 2 {
		return nil, trace.BadParameter("variable must have exactly two parts: namespace.name")
	}
	return newVar(parts[0], parts[1])
}
func buildVarExprFromProperty(base, key interface{}) (interface{}, error) {
	ref, ok := base.(namespaceRef)
	if !ok {
		return nil, trace.BadParameter("variable selector must have the form namespace[\"name\"]")
	}
	name, ok := key.(string)
	if !ok {
		return nil, trace.BadParameter("variable name must be a string")
	}
	return newVar(ref.namespace, name)
}
func newVar(namespace, name string) (VarExpr, error) {
	if namespace != "internal" && namespace != "external" && namespace != LiteralNamespace {
		return VarExpr{}, trace.BadParameter("unsupported variable namespace %q", namespace)
	}
	if name == "" {
		return VarExpr{}, trace.BadParameter("variable must have exactly two parts: namespace.name")
	}
	return VarExpr{Namespace: namespace, Name: name}, nil
}
func buildIdentifier(parts []string) (interface{}, error) {
	if len(parts) == 1 {
		if parts[0] == "internal" || parts[0] == "external" || parts[0] == LiteralNamespace {
			return namespaceRef{parts[0]}, nil
		}
		return nil, trace.BadParameter("incomplete variable %q; expected namespace.name", parts[0])
	}
	return buildVarExpr(parts)
}
func asExpr(v interface{}) (Expr, error) {
	e, ok := v.(Expr)
	if !ok {
		return nil, trace.BadParameter("expected string expression, got %T", v)
	}
	if e.Kind() != reflect.String {
		return nil, trace.BadParameter("expected string expression, got %s", fmt.Sprint(e.Kind()))
	}
	return e, nil
}
package parse

import (
	"reflect"
	"regexp"
	"strings"
	"unicode"

	"github.com/gravitational/teleport/lib/utils"
	"github.com/gravitational/trace"
	"github.com/vulcand/predicate"
)

const maxExpressionDepth = 128

// Expression is a string expression template.
type Expression struct {
	namespace, variable string
	prefix, suffix      string
	transform           transformer
	expr                Expr
}

func (p *Expression) Namespace() string { return p.namespace }
func (p *Expression) Name() string      { return p.variable }

// Interpolate evaluates the expression using traits keyed by variable name.
func (p *Expression) Interpolate(traits map[string][]string) ([]string, error) {
	return p.InterpolateWithValidation(traits, nil)
}

// InterpolateWithValidation evaluates the expression after validating every variable reference.
func (p *Expression) InterpolateWithValidation(traits map[string][]string, validate func(namespace, name string) error) ([]string, error) {
	if p.expr == nil { // Compatibility with Expressions assembled by older callers.
		if p.namespace == LiteralNamespace {
			return []string{p.variable}, nil
		}
		values, ok := traits[p.variable]
		if !ok {
			return nil, trace.NotFound("variable %s.%s is not present in traits", p.namespace, p.variable)
		}
		if validate != nil {
			if err := validate(p.namespace, p.variable); err != nil {
				return nil, err
			}
		}
		out := make([]string, 0, len(values))
		for _, value := range values {
			if p.transform != nil {
				var err error
				value, err = p.transform.transform(value)
				if err != nil {
					return nil, err
				}
			}
			if value != "" {
				out = append(out, p.prefix+value+p.suffix)
			}
		}
		if len(out) == 0 {
			return nil, trace.NotFound("interpolation produced no values")
		}
		return out, nil
	}
	ctx := EvaluateContext{VarValue: func(v VarExpr) ([]string, error) {
		if validate != nil {
			if err := validate(v.Namespace, v.Name); err != nil {
				return nil, err
			}
		}
		values, ok := traits[v.Name]
		if !ok {
			return nil, trace.NotFound("variable %s.%s is not present in traits", v.Namespace, v.Name)
		}
		return values, nil
	}}
	values, err := evalStrings(p.expr, ctx)
	if err != nil {
		return nil, err
	}
	if len(values) == 0 {
		return nil, trace.NotFound("interpolation produced no values")
	}
	out := make([]string, 0, len(values))
	for _, value := range values {
		if value != "" {
			out = append(out, p.prefix+value+p.suffix)
		}
	}
	if len(out) == 0 {
		return nil, trace.NotFound("interpolation produced no values")
	}
	return out, nil
}

// NewExpression parses a literal or a template with one expression.
func NewExpression(input string) (*Expression, error) {
	trimmed := strings.TrimSpace(input)
	open, close := strings.Index(trimmed, "{{"), strings.Index(trimmed, "}}")
	if open < 0 && close < 0 {
		return &Expression{namespace: LiteralNamespace, variable: input, expr: StringLitExpr{Value: input}}, nil
	}
	if open < 0 || close < open || strings.Index(trimmed[open+2:], "{{") >= 0 || strings.Index(trimmed[close+2:], "}}") >= 0 {
		return nil, malformed(input)
	}
	prefix := strings.TrimLeftFunc(trimmed[:open], unicode.IsSpace)
	suffix := strings.TrimRightFunc(trimmed[close+2:], unicode.IsSpace)
	body := strings.TrimSpace(trimmed[open+2 : close])
	if strings.ContainsAny(body, "{}") {
		return nil, malformed(input)
	}
	expr, err := parse(body)
	if err != nil {
		return nil, trace.BadParameter("invalid expression %q: %v", input, err)
	}
	if expr.Kind() != reflect.String {
		return nil, trace.BadParameter("expression %q must produce a string", input)
	}
	if _, literal := expr.(StringLitExpr); literal {
		return nil, trace.BadParameter("expression %q must reference a variable or call a function; quoted literals are not valid variable expressions", input)
	}
	if err := validateExpr(expr); err != nil {
		return nil, trace.BadParameter("invalid expression %q: %v", input, err)
	}
	p := &Expression{prefix: prefix, suffix: suffix, expr: expr}
	if v, ok := baseVar(expr); ok {
		p.namespace = v.Namespace
		p.variable = v.Name
		p.transform = legacyTransform(expr)
	} else {
		p.namespace = LiteralNamespace
	}
	return p, nil
}
func malformed(input string) error {
	return trace.BadParameter("malformed template usage in %q; expected a single {{ expression }}", input)
}
func baseVar(e Expr) (VarExpr, bool) {
	switch n := e.(type) {
	case VarExpr:
		return n, true
	case EmailLocalExpr:
		return baseVar(n.Inner)
	case RegexpReplaceExpr:
		return baseVar(n.Inner)
	}
	return VarExpr{}, false
}

func legacyTransform(expr Expr) transformer {
	switch node := expr.(type) {
	case EmailLocalExpr:
		return emailLocalTransformer{}
	case RegexpReplaceExpr:
		return regexpReplaceTransformer{re: node.re, replacement: node.Replacement}
	}
	return nil
}

// parse uses predicate's Go expression parser with a deliberately small function and variable language.
func parse(exprStr string) (Expr, error) {
	depth := 0
	quote := rune(0)
	escaped := false
	for _, r := range exprStr {
		if quote != 0 {
			if escaped {
				escaped = false
				continue
			}
			if r == '\\' {
				escaped = true
			} else if r == quote {
				quote = 0
			}
			continue
		}
		if r == '"' || r == '`' {
			quote = r
			continue
		}
		if r == '(' || r == '[' {
			depth++
			if depth > maxExpressionDepth {
				return nil, trace.BadParameter("expression exceeds maximum depth %d", maxExpressionDepth)
			}
		}
		if r == ')' || r == ']' {
			depth--
		}
	}
	p, err := predicate.NewParser(predicate.Def{GetIdentifier: func(parts []string) (interface{}, error) { return buildIdentifier(parts) }, GetProperty: buildVarExprFromProperty, Functions: map[string]interface{}{
		"email.local": func(args ...interface{}) (interface{}, error) {
			if len(args) != 1 {
				return nil, trace.BadParameter("email.local expects exactly 1 argument, got %d", len(args))
			}
			inner, err := asExpr(args[0])
			if err != nil {
				return nil, err
			}
			return EmailLocalExpr{Inner: inner}, nil
		},
		"regexp.replace": func(args ...interface{}) (interface{}, error) {
			if len(args) != 3 {
				return nil, trace.BadParameter("regexp.replace expects exactly 3 arguments, got %d", len(args))
			}
			inner, err := asExpr(args[0])
			if err != nil {
				return nil, err
			}
			pattern, ok := args[1].(string)
			if !ok {
				return nil, trace.BadParameter("regexp.replace pattern must be a constant string")
			}
			replacement, ok := args[2].(string)
			if !ok {
				return nil, trace.BadParameter("regexp.replace replacement must be a constant string")
			}
			re, err := compileRegex(pattern)
			if err != nil {
				return nil, err
			}
			return RegexpReplaceExpr{Inner: inner, Pattern: pattern, Replacement: replacement, re: re}, nil
		},
		"regexp.match": func(args ...interface{}) (interface{}, error) {
			if len(args) != 1 {
				return nil, trace.BadParameter("regexp.match expects exactly 1 argument, got %d", len(args))
			}
			pattern, ok := args[0].(string)
			if !ok {
				return nil, trace.BadParameter("regexp.match pattern must be a constant string")
			}
			re, err := compileRegex(pattern)
			if err != nil {
				return nil, err
			}
			return RegexpMatchExpr{Pattern: pattern, re: re}, nil
		},
		"regexp.not_match": func(args ...interface{}) (interface{}, error) {
			if len(args) != 1 {
				return nil, trace.BadParameter("regexp.not_match expects exactly 1 argument, got %d", len(args))
			}
			pattern, ok := args[0].(string)
			if !ok {
				return nil, trace.BadParameter("regexp.not_match pattern must be a constant string")
			}
			re, err := compileRegex(pattern)
			if err != nil {
				return nil, err
			}
			return RegexpNotMatchExpr{Pattern: pattern, re: re}, nil
		},
	}})
	if err != nil {
		return nil, err
	}
	parsed, err := p.Parse(exprStr)
	if err != nil {
		return nil, trace.BadParameter("%v", err)
	}
	e, ok := parsed.(Expr)
	if !ok {
		return nil, trace.BadParameter("expected an expression, got %T", parsed)
	}
	return e, nil
}

// Matcher matches strings against criteria.
type Matcher interface{ Match(string) bool }
type MatcherFn func(string) bool

func (fn MatcherFn) Match(in string) bool { return fn(in) }
func NewAnyMatcher(in []string) (Matcher, error) {
	ms := make([]Matcher, len(in))
	for i, v := range in {
		m, e := NewMatcher(v)
		if e != nil {
			return nil, trace.Wrap(e)
		}
		ms[i] = m
	}
	return MatcherFn(func(s string) bool {
		for _, m := range ms {
			if m.Match(s) {
				return true
			}
		}
		return false
	}), nil
}

